    if (left == null) return node;
    node.left = left.right;
    if (left.right != null) {
        left.right.parent = node;
    }
    left.right = node;
    left.parent = node.parent;
    node.parent = left;
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    // If the node or its left child is null, rotation cannot be performed
    if (node == null || node.left == null) {
        return node;
    }
    // Perform rotation
    TreeNode<T> leftChild = node.left;
    TreeNode<T> leftRightSubtree = leftChild.right;

    // leftChild becomes the new root of this subtree
    leftChild.right = node;
    // node becomes the left child of leftChild, with its right subtree set to leftRightSubtree
    node.left = leftRightSubtree;

    return leftChild;
}

