public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    try {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) {
                for (File child : children) {
                    forceDeleteOnExit(child);
                }
            }
        }
        file.deleteOnExit();
    } catch (SecurityException ex) {
        throw new IOException("Unable to register file for deletion on exit", ex);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) throw new NullPointerException("file");
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files == null) throw new IOException("Cannot list directory: " + file);
        for (File f : files) {
            forceDeleteOnExit(f);
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    Path path = file.toPath();
    if (Files.isSymbolicLink(path)) {
        // Treat symbolic link as a regular file: schedule delete of the link itself
        file.deleteOnExit();
        return;
    }
    if (file.isDirectory()) {
        Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path f, BasicFileAttributes attrs) throws IOException {
                f.toFile().deleteOnExit();
                return FileVisitResult.CONTINUE;
            }
            @Override
            public FileVisitResult postVisitDirectory(Path d, IOException exc) throws IOException {
                d.toFile().deleteOnExit();
                return FileVisitResult.CONTINUE;
            }
        });
    } else {
        file.deleteOnExit();
    }
}

