@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Create left part vertices
    @SuppressWarnings("unchecked")
    V vA0 = (V) new Integer(0);
    @SuppressWarnings("unchecked")
    V vA1 = (V) new Integer(1);
    @SuppressWarnings("unchecked")
    V vA2 = (V) new Integer(2);
    // Create right part vertices
    @SuppressWarnings("unchecked")
    V vB0 = (V) new Integer(3);
    @SuppressWarnings("unchecked")
    V vB1 = (V) new Integer(4);
    @SuppressWarnings("unchecked")
    V vB2 = (V) new Integer(5);
    // Add vertices to graph and result map
    target.addVertex(vA0); target.addVertex(vA1); target.addVertex(vA2);
    target.addVertex(vB0); target.addVertex(vB1); target.addVertex(vB2);
    resultMap.put("a0", vA0); resultMap.put("a1", vA1); resultMap.put("a2", vA2);
    resultMap.put("b0", vB0); resultMap.put("b1", vB1); resultMap.put("b2", vB2);
    // Add all cross edges to form a complete bipartite graph
    V[] left = (V[]) new Object[]{vA0, vA1, vA2};
    V[] right = (V[]) new Object[]{vB0, vB1, vB2};
    for (V u : left){
