@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    java.util.List<V> all = new java.util.ArrayList<>(resultMap.values());
    int n = all.size();
    if (n < 2) return;
    // split into two equal parts, left and right
    int half = n / 2;
    java.util.List<V> left = all.subList(0, half);
    java.util.List<V> right = all.subList(half, n);
    // ensure all vertices are in the graph
    for (V v : all) {
        target.addVertex(v);
    }
    // add edges between every pair from left and right
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    List<V> vertices = new ArrayList<>(target.getVertices());
    int n = vertices.size();
    int mid = n/2;
    for (int i = 0; i < mid; i++){
        V v1 = vertices.get(i);
        for (int j = mid; j < n; j++){
            V v2 = vertices.get(j);
            target.addEdge(v1, v2);
        }
    }
    // populate resultMap with vertex identifiers
    for (int k = 0; k < n; k++){
        resultMap.put("v" + k, vertices.get(k));
    }
}

