public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message into the buffer
    int size = schema.getSerializedSize(message, buffer);
    // Write the length prefix as a protobuf varint
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Write the serialized payload
    byte[] data = buffer.getBuffer();
    int dataLen = buffer.size();
    out.write(data, 0, dataLen);
    out.flush();
    // Reset the buffer for reuse
    buffer.clear();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.writeTo(cos, message, buffer);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Compute the size of the encoded message
    int size = schema.getMessageSize(message);
    // Clear the buffer and serialize the message into it
    buffer.clear();
    schema.writeTo(buffer, message);
    // Write the size as a 4-byte big-endian integer prefix
    out.write(ByteBuffer.allocate(4).putInt(size).array());
    // Write the serialized message bytes
    buffer.writeTo(out);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (buffer == null) {
        buffer = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE);
    }
    int size = schema.serializedSize(message);
    int v = size;
    while ((v & ~0x7F) != 0) {
        out.write((v & 0x7F) | 0x80);
        v >>>= 7;
    }
    out.write(v);
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    schema.writeTo(message, cos);
    cos.flush();
    return size;
}

