public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    // Only parameterized types can have arguments
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] actualArgs = pType.getActualTypeArguments();
    if (actualArgs == null || actualArgs.length == 0) {
        return null;
    }
    Class<?>[] result = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type arg = actualArgs[i];
        Class<?> resolved = null;
        if (arg instanceof Class<?>) {
            resolved = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class<?>) {
                resolved = (Class<?>) raw;
            }
        } else if (arg instanceof WildcardType) {
            WildcardType wc = (WildcardType) arg;
            Type[] upper = wc.getUpperBounds();
            if (upper != null && upper.length > 0 && upper[0] instanceof Class<?>) {
                resolved = (Class<?>) upper[0];
            }
        } else if (arg instanceof TypeVariable<?>) {
            // No type variable resolution without a map – cannot resolve
            resolved = null;
        }
        if (resolved == null) {
            return null; // cannot fully resolve the arguments
        }
        result[i] = resolved;
    }
    return result;
}

