public Mappings diffStructure(String tableName, Mappings mappings) {
    // Create a new structure to hold the differing fields
    Mappings diff = new Mappings();
    // Retrieve the current mapping for the table (implementation specific)
    Mappings current = getCurrentMappingForTable(tableName);
    if (current == null) {
        return diff;
    }
    // Iterate over each type defined in the current mapping
    for (Map.Entry<String, Map<String, Object>> typeEntry : current.getTypes().entrySet()) {
        String type = typeEntry.getKey();
        Map<String, Object> currentFields = typeEntry.getValue();
        Map<String, Object> historyFields = mappings.getTypes().getOrDefault(type, Collections.emptyMap());
        Map<String, Object> diffFields = new LinkedHashMap<>();
        // Compare fields
        for (Map.Entry<String, Object> fieldEntry : currentFields.entrySet()) {
            String fieldName = fieldEntry.getKey();
            // Skip the special _source field
            if ("_source".equalsIgnoreCase(fieldName)) {
                continue;
            }
            // Add the field if it doesn't exist in the history mapping
            if (!historyFields.containsKey(fieldName)) {
                diffFields.put(fieldName, fieldEntry.getValue());
            }
        }
        // If there are new fields, add them to the diff structure
        if (!diffFields.isEmpty()) {
            diff.addType(type, diffFields);
        }
    }
    return diff;
}

