public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null){
        return 0;
    }
    int start = index;
    int end = index + len;
    if (start < 0 || len < 0 || end > str.length()){
        return 0;
    }
    int size = 0;
    for (int i = start; i < end;){
        int cp = str.codePointAt(i);
        i += Character.charCount(cp);
        if (cp <= 0x7F){
            size += 1;
        } else if (cp <= 0x7FF){
            size += 2;
        } else if (cp <= 0xFFFF){
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int end = Math.min(index + len, str.length());
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            if (Character.isHighSurrogate(ch) && i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str == null || len <= 0 || index < 0 || index >= str.length()){
        return 0;
    }
    int end = Math.min(str.length(), index + len);
    int size = 0;
    for(int i = index; i < end; i++){
        char ch = str.charAt(i);
        int codePoint;
        if(Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))){
            codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            i++;
        } else {
            codePoint = ch;
        }
        if(codePoint <= 0x7F){
            size += 1;
        } else if(codePoint <= 0x7FF){
            size += 2;
        } else if(codePoint <= 0xFFFF){
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

