public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution on the found value
    // Assuming the substitution format is ${var} and values are taken from the same properties object
    for (String entry : props.stringPropertyNames()) {
        String placeholder = "${" + entry + "}";
        if (value.contains(placeholder)) {
            value = value.replace(placeholder, props.getProperty(entry));
        }
    }
    return value;
}

