private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int sufLen = suffix.length();
    if (sufLen > strLen) {
        return false;
    }
    int start = strLen - sufLen;
    if (!ignoreCase) {
        return str.regionMatches(start, suffix, 0, sufLen);
    } else {
        return str.regionMatches(true, start, suffix, 0, sufLen);
    }
}

