public String format(final LoggingEvent event) {
    if (event == null) {
        return "";
    }
    StringBuilder builder = new StringBuilder();
    // Append level and logger name
    builder.append(event.getLevel());
    builder.append(' ');
    builder.append(event.getLoggerName());
    builder.append(" - ");
    // Append the formatted message
    builder.append(event.getFormattedMessage());
    // If there's a throwable, include its stack trace
    if (event.getThrowableInformation() != null) {
        builder.append(System.lineSeparator());
        builder.append(event.getThrowableInformation().getThrowableStrRep());
    }
    return builder.toString();
}

