        }
    }
}

private void putAbstractTypes(final int start, final int end){
    for (int i = start; i < end; i++){
        // Retrieve the abstract type descriptor from the current frame.
        AbstractType type = currentFrame.get(i);
        // Convert the abstract type into the JVMS verification_type_info representation.
        VerificationTypeInfo verificationInfo = VerificationTypeInfo.fromAbstractType(type);
        // Append the encoded verification_type_info to the stack map table entries.
        stackMapTableEntries.add(verificationInfo);
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        Object t = currentFrame.get(i);
        if (t instanceof Integer) {                      // Integer
            stackMapTableEntries.writeByte(0x02);
        } else if (t instanceof Float) {                 // Float
            stackMapTableEntries.writeByte(0x03);
        } else if (t instanceof Long) {                  // Long
            stackMapTableEntries.writeByte(0x04);
        } else if (t instanceof Double) {                // Double
            stackMapTableEntries.writeByte(0x05);
        } else if (t instanceof String) {                // Object type (class name)
            stackMapTableEntries.writeByte(0x07);
            // Assume a helper that returns the constant pool index for an object type
            int cpIndex = constantPool.addClassInfo((String) t);
            stackMapTableEntries.writeShort(cpIndex);
        } else if (t == null) {                          // Top (unused stack element)
            stackMapTableEntries.writeByte(0x01);
        } else {
            // For reference types, we treat them as UNINITIALIZED if necessary.
            stackMapTableEntries.writeByte(0x08);
            int cpIndex = constantPool.addUninitializedObjectInfo(i);
            stackMapTableEntries.writeShort(cpIndex);
        }
    }
}

