                                if (c2 >= '0' && c2 <= '7') {
                                    val = val * 8 + (c2 - '0');
                                    j++;
                                }
                            }
                        }
                    }
                    sb.append((char) val);
                    i = j;
                } else {
                    sb.append(next);
                }
                break;
        }
    }
    return sb.toString();
}

