    // Find the actual start vertex: a source that is never a target
    java.util.Set<V> targets = new java.util.HashSet<V>();
    for (E e : tour) {
        targets.add(graph.getEdgeTarget(e));
    }
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        if (!targets.contains(src)) {
            start = src;
            break;
        }
    }

    // Find the actual end vertex: a target that is never a source
    java.util.Set<V> sources = new java.util.HashSet<V>();
    for (E e : tour) {
        sources.add(graph.getEdgeSource(e));
    }
    for (E e : tour) {
        V tgt = graph.getEdgeTarget(e);
        if (!sources.contains(tgt)) {
            end = tgt;
            break;
        }
    }

    // Create the GraphPath with the given edge set
    java.util.List<E> edgeList = new java.util.ArrayList<E>(tour);
    return new GraphPath<V,E>(graph, start, end, edgeList);
}

