protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V s = graph.getEdgeSource(e);
        V t = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(s, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(t, k -> new ArrayList<>()).add(e);
    }
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Iterator<E> it = tour.iterator();
    if (!it.hasNext()){
        return null;
    }
    E first = it.next();
    V start = graph.getEdgeSource(first);
    V next = graph.getEdgeTarget(first);
    vertices.add(start);
    edges.add(first);
    vertices.add(next);
    Set<E> used = new HashSet<>();
    used.add(first);
    V current = next;
    while (used.size() < tour.size()){
        List<E> adj = adjacency.get(current);
        if (adj == null){
            break;
        }
        E candidate = null;
        for (E e : adj){
            if (!used.contains(e)){
                candidate = e;
                break;
            }
        }
        if (candidate == null){
            break;
        }
        used.add(candidate);
        edges.add(candidate);
        V other = graph.getEdgeSource(candidate).equals(current) ? graph.getEdgeTarget(candidate) : graph.getEdgeSource(candidate);
        vertices.add(other);
        current = other;
    }
    return new GraphPathImpl<>(graph, vertices, edges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty()){
        return null;
    }
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    List<E> orderedEdges = new ArrayList<>();
    // Use the first edge as the starting point
    E startEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(startEdge);
    V nextVertex = graph.getEdgeTarget(startEdge);
    vertexList.add(startVertex);
    vertexList.add(nextVertex);
    orderedEdges.add(startEdge);
    // Mark edges as used
    int remaining = edgeList.size() - 1;
    int currentIndex = 0;
    while(remaining > 0){
        boolean found = false;
        V currentVertex = vertexList.get(vertexList.size() - 1);
        for(int i = currentIndex; i < edgeList.size(); i++){
            E e = edgeList.get(i);
            if(orderedEdges.contains(e)){
                continue;
            }
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if(src.equals(currentVertex)){
                vertexList.add(tgt);
                orderedEdges.add(e);
                found = true;
                break;
            } else if(tgt.equals(currentVertex)){
                vertexList.add(src);
                orderedEdges.add(e);
                found = true;
                break;
            }
        }
        if(!found){
            // No connecting edge found; break out of loop
            break;
        }
        remaining--;
    }
    // If we did not build a continuous tour, return null
    if(orderedEdges.size() != tour.size()){
        return null;
    }
    return new SimpleGraphPath<>(graph, vertexList, orderedEdges);
}

