    int lastDotIndex = path.lastIndexOf('.');
    if (lastDotIndex <= lastSeparatorIndex || lastDotIndex <= 0) {
        return null;
    }
    String result = path.substring(0, lastDotIndex);
    return result.isEmpty() ? null : result;
}

