private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list.head == null || list == this){
        return;
    }
    if (this.head == null){
        this.head = list.head;
        this.tail = list.tail;
        this.size += list.size;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
        this.size += list.size;
    }
    list.head = null;
    list.tail = null;
    list.size = 0;
}

