private void function ( DoublyLinkedList<E> list ) {
    if ( list.isEmpty() ) return;
    // Assume each list has sentinel head and tail nodes
    ListNodeImpl<E> firstSrc = list.head.next;
    ListNodeImpl<E> lastSrc  = list.tail.prev;

    ListNodeImpl<E> lastDest = this.tail.prev;
    // Link last node of destination to first node of source
    lastDest.next = firstSrc;
    firstSrc.prev = lastDest;

    // Link last node of source to tail sentinel of destination
    lastSrc.next = this.tail;
    this.tail.prev = lastSrc;

    // Reset source list to empty
    list.head.next = list.tail;
    list.tail.prev = list.head;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode<E> current = list.head;
    ListNode<E> next;
    while (current != null) {
        next = current.next;
        list.removeListNode(current);
        this.addListNode(current);
        current = next;
    }
}

