public void abbreviate(final int nameStart, final StringBuffer buf){
    if (name == null) return;
    int len = name.length();
    boolean next = true;
    for (int i = nameStart; i < len; i++) {
        char ch = name.charAt(i);
        if (Character.isWhitespace(ch)) {
            next = true;
        } else {
            if (next) {
                buf.append(Character.toUpperCase(ch));
                buf.append('.');
                next = false;
            }
        }
    }
}

