public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    boolean leadingSlash = path.startsWith("/");
    java.util.List<String> parts = new java.util.ArrayList<>();
    String[] baseSegs = path.split("/");
    for (String seg : baseSegs) {
        if (!seg.isEmpty()) {
            parts.add(seg);
        }
    }
    String[] relSegs = relativePath.split("/");
    for (String seg : relSegs) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!parts.isEmpty()) {
                // Don't go above root
                if (!(parts.get(parts.size() - 1).equals("..") && !leadingSlash)) {
                    parts.remove(parts.size() - 1);
                } else {
                    parts.add("..");
                }
            } else {
                // If no base part, just keep ".." which would navigate up from current location
                parts.add("..");
            }
        } else {
            parts.add(seg);
        }
    }
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(parts.get(i));
    }
    return result.toString();
}

