List<ThreadSnapshot> function (File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> all = parseFromFile(file);
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    for (ThreadSnapshot snapshot : all) {
        long time = snapshot.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (time >= range.getStart() && time <= range.getEnd()) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty())
                continue;
            String[] parts = line.split(",", 2);
            long ts = Long.parseLong(parts[0].trim());
            String data = parts.length > 1 ? parts[1] : "";
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (ts >= range.getStartMillis() && ts <= range.getEndMillis()) {
                    result.add(new ThreadSnapshot(ts, data));
                    break;
                }
            }
        }
    }
    return result;
}

