public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    // Read all lines from the file
    List<String> lines = java.nio.file.Files.readAllLines(file.toPath());
    for (String line : lines) {
        // Attempt to parse a ThreadSnapshot from the line
        ThreadSnapshot snapshot;
        try {
            snapshot = ThreadSnapshot.parse(line);
        } catch (Exception e) {
            // If parsing fails, skip this line
            continue;
        }
        // If time ranges are specified, filter snapshots by timestamp
        if (timeRanges != null && !timeRanges.isEmpty()) {
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange tr : timeRanges) {
                // Assume getTimestamp() returns a long representing the snapshot time
                if (tr.contains(snapshot.getTimestamp())) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }
        }
        snapshots.add(snapshot);
    }
    return snapshots;
}
